messages.content:
I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  data
 - output count (4 bits)
 - output counting
 - output done
 - input  ack

The module should implement a timer with one input that:

  (1) is started when a particular input pattern (1101) is detected,
  (2) shifts in 4 more bits to determine the duration to delay,
  (3) waits for the counters to finish counting, and
  (4) notifies the user and waits for the user to acknowledge the timer.

The serial data is available on the data input pin. When the pattern 1101
is received, the circuit must then shift in the next 4 bits,
most-significant-bit first. These 4 bits determine the duration of the
timer delay, referred to as delay[3:0]. After that, the state machine
asserts its counting output to indicate it is counting. Once the 1101 and
delay[3:0] have been read, the circuit no longer looks at the data input
until it resumes searching after everything else is done.

The state machine must count for exactly (delay[3:0] + 1) * 1000 clock
cycles. e.g., delay=0 means count 1000 cycles, and delay=5 means count
6000 cycles. Also output the current remaining time. This should be equal
to delay for 1000 cycles, then delay-1 for 1000 cycles, and so on until
it is 0 for 1000 cycles.

When the circuit isn't counting, the count[3:0] output is don't-care
(whatever value is convenient for you to implement). At that point, the
circuit must assert done to notify the user the timer has timed out, and
waits until input ack is 1 before being reset to look for the next
occurrence of the start sequence (1101).

The circuit should reset into a state where it begins searching for the
input sequence 1101. The reset signal is active high synchronous. Assume
all sequential logic is triggered on the positive edge of the clock.

Previous candidate:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    // State encoding
    // S0: Search for '1'
    // S1: Found '1', search for '1'
    // S2: Found '11', search for '0'
    // S3: Found '110', search for '1' -> Start detected
    // S4: Shift in delay[3] (MSB)
    // S5: Shift in delay[2]
    // S6: Shift in delay[1]
    // S7: Shift in delay[0] (LSB)
    // S8: Counting
    // S9: Done, wait for ack

    typedef enum logic [3:0] {
        S0 = 4'd0,
        S1 = 4'd1,
        S2 = 4'd2,
        S3 = 4'd3,
        S4 = 4'd4,
        S5 = 4'd5,
        S6 = 4'd6,
        S7 = 4'd7,
        S8 = 4'd8,
        S9 = 4'd9
    } state_t;

    state_t state, next_state;

    // Registers
    logic [3:0] delay_reg;
    logic [3:0] count_reg;
    logic [9:0] cycle_cnt; // Counts up to 1000 (0 to 999)
    logic counting_reg;
    logic done_reg;

    // Default assignments for combinational logic to avoid latches
    assign count = (state == S8) ? count_reg : 4'b0;
    assign counting = counting_reg;
    assign done = done_reg;

    // Next state logic and output logic
    always_comb begin
        next_state = state;
        delay_reg = delay_reg;
        count_reg = count_reg;
        cycle_cnt = cycle_cnt;
        counting_reg = 1'b0;
        done_reg = 1'b0;

        case (state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0; // Mismatch, restart search. Note: if data is 0, it's not start of 1101, so go to S0.
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = S2; // If data is 1, we have '111', which is '11' followed by '1'. The last two bits are '11', so stay in S2.
            end
            S3: begin
                if (data == 1'b1)
                    next_state = S4; // Pattern 1101 detected
                else
                    next_state = S0; // Mismatch. If data is 0, sequence is 1100. No prefix of 1101 matches suffix of 1100 except empty.
            end
            S4: begin
                // Shift in MSB of delay
                delay_reg = {delay_reg[2:0], data};
                next_state = S5;
            end
            S5: begin
                delay_reg = {delay_reg[2:0], data};
                next_state = S6;
            end
            S6: begin
                delay_reg = {delay_reg[2:0], data};
                next_state = S7;
            end
            S7: begin
                delay_reg = {delay_reg[2:0], data};
                next_state = S8;
                count_reg = delay_reg;
                cycle_cnt = 10'd0;
                counting_reg = 1'b1;
            end
            S8: begin
                counting_reg = 1'b1;
                if (cycle_cnt == 10'd999) begin
                    // End of 1000 cycles
                    if (count_reg == 4'd0) begin
                        // Counting finished
                        next_state = S9;
                        counting_reg = 1'b0;
                        done_reg = 1'b1;
                    end else begin
                        // Decrement count and reset cycle counter
                        count_reg = count_reg - 1;
                        cycle_cnt = 10'd0;
                    end
                end else begin
                    cycle_cnt = cycle_cnt + 1;
                end
            end
            S9: begin
                done_reg = 1'b1;
                if (ack == 1'b1) begin
                    next_state = S0;
                    done_reg = 1'b0;
                end
            end
            default: next_state = S0;
        endcase
    end

    // Sequential logic
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S0;
            delay_reg <= 4'b0;
            count_reg <= 4'b0;
            cycle_cnt <= 10'd0;
            counting_reg <= 1'b0;
            done_reg <= 1'b0;
        end else begin
            state <= next_state;
            delay_reg <= delay_reg; // Updated in combinational logic for S4-S7
            count_reg <= count_reg; // Updated in combinational logic for S8
            cycle_cnt <= cycle_cnt; // Updated in combinational logic for S8
            counting_reg <= counting_reg;
            done_reg <= done_reg;
        end
    end

endmodule

